from pathlib import Path
import matplotlib.pyplot as plt
import math, statistics
import numpy as np

SSIRD_PLOT_COLOUR = 'tab:orange'
IDEAL_PLOT_COLOUR = 'tab:blue'

LINK_SPEED_GIGABITS_PER_SEC = 100 # 100 GBps link speed
LINK_SPEED_BITS_PER_SEC = LINK_SPEED_GIGABITS_PER_SEC * pow(10,9)

RTT_5US_S = 5 * pow(10,-6) # 5us RTT
RTT_1MS_S = 1 * pow(10,-3) # 1ms RTT

MAX_R2P2_PAYLOAD_B = 1458
DATA_PKT_HEADER_SIZE_B = 80
CREDIT_REQ_PKT_SIZE_B = 84

# PATH_TO_SCRIPTS_R2P2 = "/home/dalehuang/Documents/ICL/msc_proj/SIRD-Simulator/scripts/r2p2/"
PATH_TO_SCRIPTS_R2P2 = "/data/dh1723/SIRD-Simulator/scripts/r2p2/" # NOTE: this is for batch1 server
PATH_TO_POSTPROC = f"{PATH_TO_SCRIPTS_R2P2}post-process/"
PATH_TO_TMP_PLOT = PATH_TO_POSTPROC + "tmp_plot/"
PATH_TO_FCT_SLOWDOWN_PLOTS = PATH_TO_TMP_PLOT + "fct_slowdown_analysis/"

VARY_BLOAD_SIZE = "Varying Byteload Size"
VARY_INTERVAL = "Varying Intervals"

def get_theoretical_fct_parallel_flows_s(num_flows, num_byteloads_per_flow_list, byteload_size_B_list, inter_byteload_interval_us_list, rtt_s):
    '''
    NOTE: this is for exactly-parallel flows ONLY! All byteloads in each flow must be in sync with those in all other flows.
    '''
    num_experiments = len(num_byteloads_per_flow_list)
    assert(num_experiments == len(byteload_size_B_list))
    assert(num_experiments == len(inter_byteload_interval_us_list))
    inter_byteload_interval_s_list = [s * pow(10,-6) for s in inter_byteload_interval_us_list]

    theoretical_fct_s_list = []
    theoretical_thrpt_gbps_list = []
    for i in range(0, num_experiments):
        fct = None
        # Approximation way:
        # app_gdpt_bps = num_flows * byteload_size_B_list[i] * 8 / inter_byteload_interval_s_list[i]
        # thrpt_bps = min(LINK_SPEED_BITS_PER_SEC, app_gdpt_bps)
        # flow_size_b = num_byteloads_per_flow_list[i] * byteload_size_B_list[i] * 8
        # total_data_transmitted_b = num_flows * flow_size_b
        # fct = 0.5*rtt_s + total_data_transmitted_b/thrpt_bps

        # app_gdpt_bps = num_flows * byteload_size_B_list[i] * 8 / inter_byteload_interval_s_list[i]
        # thrpt_bps = min(LINK_SPEED_BITS_PER_SEC, app_gdpt_bps)
        # if (byteload_size_B_list[i] > 1):
        #     flow_size_b = (num_byteloads_per_flow_list[i] - 1) * byteload_size_B_list[i] * 8
        #     total_data_transmitted_b = num_flows * flow_size_b
        #     fct = 0.5*rtt_s + total_data_transmitted_b/thrpt_bps + num_flows*byteload_size_B_list[i]*8/LINK_SPEED_BITS_PER_SEC
        # else:
        #     fct = 0.5*rtt_s + num_flows*byteload_size_B_list[i]*8/LINK_SPEED_BITS_PER_SEC

        app_gdpt_bps = num_flows * byteload_size_B_list[i] * 8 / inter_byteload_interval_s_list[i]
        if (app_gdpt_bps > LINK_SPEED_BITS_PER_SEC):
            flow_size_b = num_byteloads_per_flow_list[i] * byteload_size_B_list[i] * 8
            total_data_transmitted_b = num_flows * flow_size_b
            fct = 0.5*rtt_s + total_data_transmitted_b/LINK_SPEED_BITS_PER_SEC 
        else:
            if (byteload_size_B_list[i] > 1):
                flow_size_b = (num_byteloads_per_flow_list[i] - 1) * byteload_size_B_list[i] * 8
                total_data_transmitted_b = num_flows * flow_size_b
                fct = 0.5*rtt_s + total_data_transmitted_b/app_gdpt_bps + num_flows*byteload_size_B_list[i]*8/LINK_SPEED_BITS_PER_SEC
            else:
                fct = 0.5*rtt_s + num_flows*byteload_size_B_list[i]*8/LINK_SPEED_BITS_PER_SEC

        # # Exact-ish way:
        num_data_pkts_per_byteload = max(math.ceil(byteload_size_B_list[i] / MAX_R2P2_PAYLOAD_B), 1)
        d_hdr_overhead_per_byteload_B = DATA_PKT_HEADER_SIZE_B * num_data_pkts_per_byteload
        
        theoretical_total_data_per_interval_B = num_flows * (byteload_size_B_list[i] + d_hdr_overhead_per_byteload_B + CREDIT_REQ_PKT_SIZE_B)
        theoretical_thrpt_per_interval_bps = theoretical_total_data_per_interval_B * 8 / inter_byteload_interval_s_list[i]
        theoretical_thrpt_gbps_list.append(theoretical_thrpt_per_interval_bps/pow(10,9))
        if (theoretical_thrpt_per_interval_bps > LINK_SPEED_BITS_PER_SEC):
            print(f"NB: Theoretical thrpt (with overheads) exceeds link speed! Bload size: {byteload_size_B_list[i]}B, Interval: {inter_byteload_interval_us_list[i]}us; Theoretical total data per interval: {theoretical_total_data_per_interval_B}B, Theoretical Thrpt: {theoretical_thrpt_per_interval_bps/pow(10,9)}Gbps")

        # # NOTE: ideal FCT should not include overheads from credit requests and data.
        # if (num_byteloads_per_flow_list[i] > 1):
        #     # fct = (num_byteloads_per_flow_list[i] - 1) * inter_byteload_interval_s_list[i] + num_flows * (byteload_size_B_list[i] + d_hdr_overhead_per_byteload_B + CREDIT_REQ_PKT_SIZE_B) * 8 / float(LINK_SPEED_BITS_PER_SEC) 
        #     fct = (num_byteloads_per_flow_list[i]-1)*inter_byteload_interval_s_list[i] + 0.5*rtt_s + num_flows*(byteload_size_B_list[i])*8/float(LINK_SPEED_BITS_PER_SEC) 
        # else:
        #     # fct = num_flows * (byteload_size_B_list[i] + d_hdr_overhead_per_byteload_B + CREDIT_REQ_PKT_SIZE_B) * 8 / float(LINK_SPEED_BITS_PER_SEC) 
        #     fct = 0.5*rtt_s + num_flows*(byteload_size_B_list[i])*8/float(LINK_SPEED_BITS_PER_SEC) 

        theoretical_fct_s_list.append(fct)

    print(f"-- Theoretical thrpt per interval: {theoretical_thrpt_gbps_list}")
    return theoretical_fct_s_list

def plot_fct_vs_interval_ssird_vs_ideal(inter_byteload_period_us_list, ssird_fct_s_list, ideal_fct_s_list, num_flows, flow_size_B, total_gdpt_gbps, title_addendum="", is_log_x=False, is_log_y=False, y_lim=None):
    ssird_fct_ms_list = [t * 1000 for t in ssird_fct_s_list]
    ideal_fct_ms_list = [t * 1000 for t in ideal_fct_s_list]

    plt.figure(figsize=(10, 6))
    plt.plot(inter_byteload_period_us_list, ssird_fct_ms_list, label="SSIRD", linestyle='-', marker='o', color=SSIRD_PLOT_COLOUR)
    plt.plot(inter_byteload_period_us_list, ideal_fct_ms_list, label="Ideal (theory)", linestyle='-', marker='o', color=IDEAL_PLOT_COLOUR)
    plt.xlabel('Inter-Byteload Interval (us)')
    plt.ylabel('Flow Completion Time (ms)')
    plt.title(f"FCT: SSIRD vs Ideal: Varying Intervals\n({num_flows} Flows; {flow_size_B}B per Flow; {total_gdpt_gbps}Gbps Total Goodput)\n {title_addendum}")
    plt.legend()
    plt.grid(True)
    if (is_log_x): plt.xscale('log')
    if (is_log_y): plt.yscale('log')
    if (y_lim): plt.ylim(y_lim)

    Path(PATH_TO_FCT_SLOWDOWN_PLOTS).mkdir(parents=True, exist_ok=True)
    filename_prefix = "FCT_VARY_INTERVAL_"
    filename = f"{filename_prefix}ssird_vs_ideal_{num_flows}flo_{flow_size_B}BperFlo_{total_gdpt_gbps}GbpsGdpt{title_addendum}.png"
    plt.savefig(f"{PATH_TO_FCT_SLOWDOWN_PLOTS}{filename}")
    plt.close()

def plot_fct_vs_byteload_size_ssird_vs_ideal(byteload_size_B_list, ssird_fct_s_list, ideal_fct_s_list, num_flows, flow_size_B, total_gdpt_gbps, title_addendum="", is_log_x=False, is_log_y=False, y_lim=None):
    ssird_fct_ms_list = [t * 1000 for t in ssird_fct_s_list]
    ideal_fct_ms_list = [t * 1000 for t in ideal_fct_s_list]

    plt.figure(figsize=(10, 6))
    plt.plot(byteload_size_B_list, ssird_fct_ms_list, label="SSIRD", linestyle='-', marker='o', color=SSIRD_PLOT_COLOUR)
    plt.plot(byteload_size_B_list, ideal_fct_ms_list, label="Ideal (theory)", linestyle='-', marker='o', color=IDEAL_PLOT_COLOUR)
    plt.xlabel('Byteload Size (B)')
    plt.ylabel('Flow Completion Time (ms)')
    plt.title(f"FCT: SSIRD vs Ideal: Varying Byteload Size\n({num_flows} Flows; {flow_size_B}B per Flow; {total_gdpt_gbps}Gbps Total Goodput)\n {title_addendum}")
    plt.legend()
    plt.grid(True)
    if (is_log_x): plt.xscale('log')
    if (is_log_y): plt.yscale('log')
    if (y_lim): plt.ylim(y_lim)

    Path(PATH_TO_FCT_SLOWDOWN_PLOTS).mkdir(parents=True, exist_ok=True)
    filename_prefix = "FCT_VARY_BLOAD_SIZE_"
    filename = f"{filename_prefix}ssird_vs_ideal_{num_flows}flo_{flow_size_B}BperFlo_{total_gdpt_gbps}GbpsGdpt{title_addendum}.png"
    plt.savefig(f"{PATH_TO_FCT_SLOWDOWN_PLOTS}{filename}")
    plt.close()

def plot_fct_diff_ssird_vs_ideal(experiment_type, x_vals_list, ssird_fct_s_list, ideal_fct_s_list, num_flows, flow_size_B, total_gdpt_gbps, title_addendum="", is_log_x=False, is_log_y=False, y_lim=None):
    fct_diff_s_list = [s - i for s, i in zip(ssird_fct_s_list, ideal_fct_s_list)]
    fct_diff_us_list = [x * pow(10,6) for x in fct_diff_s_list]

    plt.figure(figsize=(10, 6))
    plt.plot(x_vals_list, fct_diff_us_list, label="SSIRD - IDEAL", linestyle='-', marker='o', color=SSIRD_PLOT_COLOUR)

    if experiment_type == VARY_BLOAD_SIZE:
        plt.xlabel('Byteload Size (B)')
        filename_prefix = "FCT_DIFF_VARY_BLOAD_SIZE_"
    elif experiment_type == VARY_INTERVAL:
        plt.xlabel('Inter-Byteload Interval (us)')
        filename_prefix = "FCT_DIFF_VARY_INTERVAL_"
    print(f"{filename_prefix:} FCT Diff (us): {fct_diff_us_list}")

    plt.ylabel('Flow Completion Time DIFF (us)')
    plt.title(f"FCT Diff: SSIRD vs Ideal: {experiment_type}\n({num_flows} Flows; {flow_size_B}B per Flow; {total_gdpt_gbps}Gbps Total Goodput)\n {title_addendum}")
    plt.legend()
    plt.grid(True)
    if (is_log_x): plt.xscale('log')
    if (is_log_y): plt.yscale('log')
    if (y_lim): plt.ylim(y_lim)

    Path(PATH_TO_FCT_SLOWDOWN_PLOTS).mkdir(parents=True, exist_ok=True)
    filename = f"{filename_prefix}ssird_vs_ideal_{num_flows}flo_{flow_size_B}BperFlo_{total_gdpt_gbps}GbpsGdpt{title_addendum}.png"
    plt.savefig(f"{PATH_TO_FCT_SLOWDOWN_PLOTS}{filename}")
    plt.close()

def plot_fct_slowdown_ssird_vs_ideal(experiment_type, x_vals_list, ssird_fct_s_list, ideal_fct_s_list, num_flows, flow_size_B, total_gdpt_gbps, title_addendum="", is_log_x=False, is_log_y=False, y_lim=None):
    fct_slowdown_list = [s/i for s, i in zip(ssird_fct_s_list, ideal_fct_s_list)]

    plt.figure(figsize=(10, 6))
    plt.plot(x_vals_list, fct_slowdown_list, label="SSIRD/IDEAL", linestyle='-', marker='o', color=SSIRD_PLOT_COLOUR)

    if experiment_type == VARY_BLOAD_SIZE:
        plt.xlabel('Byteload Size (B)')
        filename_prefix = "FCT_SLOWDOWN_VARY_BLOAD_SIZE_"
    elif experiment_type == VARY_INTERVAL:
        plt.xlabel('Inter-Byteload Interval (us)')
        filename_prefix = "FCT_SLOWDOWN_VARY_INTERVAL_"
    print(f"{filename_prefix:} Slowdown: {fct_slowdown_list}")

    plt.ylabel('FCT Slowdown')
    plt.title(f"FCT Slowdown: SSIRD vs Ideal: {experiment_type}\n({num_flows} Flows; {flow_size_B}B per Flow; {total_gdpt_gbps}Gbps Total Goodput)\n {title_addendum}")
    plt.legend()
    plt.grid(True)
    if (is_log_x): plt.xscale('log')
    if (is_log_y): plt.yscale('log')
    if (y_lim): plt.ylim(y_lim)

    Path(PATH_TO_FCT_SLOWDOWN_PLOTS).mkdir(parents=True, exist_ok=True)
    filename = f"{filename_prefix}ssird_vs_ideal_{num_flows}flo_{flow_size_B}BperFlo_{total_gdpt_gbps}GbpsGdpt{title_addendum}.png"
    plt.savefig(f"{PATH_TO_FCT_SLOWDOWN_PLOTS}{filename}")
    plt.close()


def analyse_fct_slowdown_ssird_vs_ideal(inter_byteload_period_us_list, num_byteloads_list, byteload_size_B_list, ssird_fct_s_list_list, dctcp_fct_s_list_list, num_flows, flow_size_B, total_gdpt_gbps, rtt_s=RTT_5US_S, title_addendum=""):
    # NOTE: max 1 out of 15 flows is 93rd percentile 
    ssird_fct_s_max_list = [max(l) for l in ssird_fct_s_list_list]
    dctcp_fct_s_max_list = [max(l) for l in dctcp_fct_s_list_list]
    print(f"SSIRD FCT (s) MAX:{ssird_fct_s_max_list}")
    print(f"DCTCP FCT (s) MAX:{dctcp_fct_s_max_list}")

    # ssird_fct_s_mean_list = [statistics.mean(l) for l in ssird_fct_s_list_list]
    # dctcp_fct_s_mean_list = [statistics.mean(l) for l in dctcp_fct_s_list_list]
    # print(f"SSIRD FCT (s) MEAN:{ssird_fct_s_mean_list}")
    # print(f"DCTCP FCT (s) MEAN:{ideal_fct_s_mean_list}")

    theoretical_fct_parallel_flows_s_list = get_theoretical_fct_parallel_flows_s(num_flows, num_byteloads_list, byteload_size_B_list, inter_byteload_period_us_list, rtt_s)
    print(f"THEORETICAL IDEAL Exactly-parallel FCT (s):{theoretical_fct_parallel_flows_s_list}")

    ssird_fct_s_list = ssird_fct_s_max_list
    # print("*** VS THEORY")
    # ideal_fct_s_list = theoretical_fct_parallel_flows_s_list 
    print("*** VS DCTCP")
    ideal_fct_s_list = dctcp_fct_s_max_list 

    # Plot FCT
    plot_fct_vs_interval_ssird_vs_ideal(inter_byteload_period_us_list, ssird_fct_s_list, ideal_fct_s_list, num_flows, flow_size_B, total_gdpt_gbps, title_addendum, is_log_x=True, y_lim=None)
    plot_fct_vs_byteload_size_ssird_vs_ideal(byteload_size_B_list, ssird_fct_s_list, ideal_fct_s_list, num_flows, flow_size_B, total_gdpt_gbps, title_addendum, is_log_x=True, y_lim=None)

    # Plot FCT Diff
    # fct_diff_ylim = (0, 2000)
    fct_diff_ylim = None
    plot_fct_diff_ssird_vs_ideal(VARY_INTERVAL, inter_byteload_period_us_list, ssird_fct_s_list, ideal_fct_s_list, num_flows, flow_size_B, total_gdpt_gbps, title_addendum, is_log_x=True, y_lim=fct_diff_ylim)
    plot_fct_diff_ssird_vs_ideal(VARY_BLOAD_SIZE, byteload_size_B_list, ssird_fct_s_list, ideal_fct_s_list, num_flows, flow_size_B, total_gdpt_gbps, title_addendum, is_log_x=True, y_lim=fct_diff_ylim)

    # Plot FCT Slowdown
    # fct_slowdown_ylim = (0, 4)
    fct_slowdown_ylim = None
    plot_fct_slowdown_ssird_vs_ideal(VARY_INTERVAL, inter_byteload_period_us_list, ssird_fct_s_list, ideal_fct_s_list, num_flows, flow_size_B, total_gdpt_gbps, title_addendum, is_log_x=True, y_lim=fct_slowdown_ylim)
    plot_fct_slowdown_ssird_vs_ideal(VARY_BLOAD_SIZE, byteload_size_B_list, ssird_fct_s_list, ideal_fct_s_list, num_flows, flow_size_B, total_gdpt_gbps, title_addendum, is_log_x=True, y_lim=fct_slowdown_ylim)

