def analyse_ssird_vs_ideal_fct_largepkt_extended_31flo_49Gbps_gdpt():
    title_addendum = "_large_bloads_extended_31flo"

    rtt_s = RTT_5US_S
    num_flows = 31
    flow_size_B = 2000000
    total_gdpt_gbps = 49.6
    inter_byteload_period_us_list = [1.0, 10.0, 100.0, 1000.0, 10000.0]
